-- Real source observations are append-only; historical catalogue values remain unchanged.
ALTER TABLE "glean_paper" ADD COLUMN "origin" character varying NOT NULL DEFAULT 'historical';
ALTER TABLE "glean_membership" ADD COLUMN "inclusion_status" character varying NOT NULL DEFAULT 'historical';
ALTER TABLE "glean_venue" ADD COLUMN "issns" jsonb NOT NULL DEFAULT '[]', ADD COLUMN "aliases" jsonb NOT NULL DEFAULT '[]';
ALTER TABLE "glean_venue" ALTER COLUMN "issns" DROP DEFAULT, ALTER COLUMN "aliases" DROP DEFAULT;
CREATE TABLE "glean_observation" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "paper_id" bigint NOT NULL, "run_id" bigint NOT NULL, "source" character varying NOT NULL, "source_id" character varying NOT NULL, "version" character varying NOT NULL DEFAULT '', "content_hash" character varying NOT NULL, "observed_at" timestamptz NOT NULL, "source_updated_at" timestamptz NULL, "metadata" jsonb NOT NULL, "publication_events" jsonb NOT NULL, "review" jsonb NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "gleanobservation_source_source_id_content_hash" ON "glean_observation" ("source", "source_id", "content_hash");
CREATE INDEX "gleanobservation_paper_id_observed_at_id" ON "glean_observation" ("paper_id", "observed_at", "id");
CREATE INDEX "gleanobservation_run_id" ON "glean_observation" ("run_id");
CREATE TABLE "glean_observation_match" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "observation_id" bigint NOT NULL, "topic" character varying NOT NULL, "template_version" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "gleanobservationmatch_observation_id_topic" ON "glean_observation_match" ("observation_id", "topic");
CREATE INDEX "gleanobservationmatch_topic" ON "glean_observation_match" ("topic");
